import {packet,money} from './invoice-packet';
export function embeddedGeneratePacket(gross=117.7){
 const base=packet(1),net=gross/1.177,service=net*.1,vat=gross*7/107,date='2026-01-02';
 const posting={hotelId:'KAT',folioNo:88,folioWindowNo:1,guestInfo:{reservationId:{id:'777'}},transactionNo:10001,transactionCode:'FOOD',transactionType:'Revenue',transactionDate:date,debitAmount:money(gross),postedAmount:money(gross)};
 const taxes=[{transactionNo:20001,referenceTransactionNo:10001,transactionCode:'NONREV',transactionDate:date,amount:money(service)},{transactionNo:20002,referenceTransactionNo:10001,transactionCode:'VAT',transactionDate:date,amount:money(vat)}];
 const p={...base,manifest:{...base.manifest,open:gross},invoice:{...base.invoice,amount:money(gross),balance:money(gross),internalFolioWindowID:'456'},postings:{invoicePostingsDetails:[{transactionNo:10001,transactionCode:'FOOD',transactionDate:date,debitAmount:money(gross),checkNo:'CHECK',reference:''}],trxCodesInfo:[{hotelId:'KAT',transactionCode:'FOOD',transactionGroup:'F&B',description:'Food'}]},taxRows:[{posting,postingBreakdown:{grossAmount:money(gross),netAmount:money(net),taxes}}],taxCodes:[{hotelId:'KAT',transactionCode:'NONREV',transactionGroup:'F&B',description:'Generated component SVC'},{hotelId:'KAT',transactionCode:'VAT',transactionGroup:'TAX',description:'VAT'}],arDetails:[]};
 const flags=(bucket1=false)=>({bucket1,bucket2:false,bucket3:false});
 const gen=(code:string,amount:number,calculatedOn:string,bucket1=false)=>({code,level:'TransactionCode',rule:{percentage:{amount,calculatedOn,useTaxBracket:false},posting:{adjustmentType:'NoAdjustment'}},addGeneratedAmtTo:flags(bucket1)});
 const rules={transactionCode:{hotelId:'KAT',code:'FOOD',classification:{type:'Revenue',transactionType:{code:'FoodAndBeverage'},group:{code:'F&B'}},trxSetup:{generatesType:'INCLUSIVE',taxInclusive:true,nonTaxable:false},compTransaction:false,associatedTransactionCodes:[],generatesSetup:{addBaseAmtTo:flags(true),generates:[gen('NONREV',10,'Base',true),gen('VAT',7,'Bucket1')]}}};
 const leaf=(code:string,kind:string,group:string)=>({transactionCode:{hotelId:'KAT',code,description:{defaultText:code},classification:{type:'Revenue',transactionType:{code:kind,...kind==='Tax'?{taxCode:1}:{}},group:{code:group}},trxSetup:{nonTaxable:false,taxInclusive:false,manualPosting:false},compTransaction:false,associatedTransactionCodes:[],generatesSetup:{addBaseAmtTo:flags()}}});
 const generatedRules=[leaf('NONREV','NonRevenue','F&B'),leaf('VAT','Tax','TAX')],group={postingId:'10001',generateIds:['20001','20002'],rules,rulesAfter:structuredClone(rules),generatedRules,generatedRulesAfter:structuredClone(generatedRules)};
 return {...p,embeddedGenerateProof:{version:1 as const,sourceBefore:structuredClone(p),sourceAfter:structuredClone(p),groups:[group]}};
}
